import{z as l,x as A,o as E,c as p,q as o,j as r,D as e,d as B,s as i,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"交易速度与市场质量","description":"","frontmatter":{"title":"交易速度与市场质量","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/speed-market-quality.md","filePath":"quant/speed-market-quality.md","lastUpdated":1791063341000}'),d={name:"quant/speed-market-quality.md"};function m(c,a,u,h,F,C){const n=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=o('<h1 id="交易速度与市场质量" tabindex="-1">交易速度与市场质量 <a class="header-anchor" href="#交易速度与市场质量" aria-label="Permalink to &quot;交易速度与市场质量&quot;">​</a></h1><div class="epigraph"><p>把整个市场变快，不等于把每笔交易的延迟差消灭。质量取决于相对速度如何被协议处理：发现可以加快，价差与深度却可以因竞赛与撤退而变差。</p><footer>—— Pagnotta and Philippon, Competing on Speed, American Economic Review, 2018；算法交易与流动性见 Hendershott, Jones and Menkveld, Journal of Finance, 2011</footer></div><p><a href="/quant/microstructure-invariance">不变量</a>给出跨品种缩放。缺口是政策变量「速度」本身：交易所升级、托管、取消地板，市场质量如何变。Pagnotta 与 Philippon（2018）把场所之间的速度竞争写成均衡；HJM（2011）提供算法交易改善流动性的证据。本课收束高频单元：质量是多指标，速度不是单调的善。然后交给市场设计续，从订单类型与场所规则动手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场质量至少包括：价差、深度、实现冲击、价格发现（Hasbrouck 误差、VR）、波动螺旋的脆弱性、以及分配（谁付速度税）。绝对延迟下降（所有人快 10 微秒）若保持相对排序，狙击期权 \\(s\\) 仍在，竞赛投入可能不变甚至因交易更密而增加。相对延迟下降（随机化、批量、颠簸）才砍 \\(s\\)。问题是经验里看到的「变快」多是哪一种：托管是相对速度的军备；自动报价更多是处理成本下降。</p><p>HJM 的流动性改善，更接近处理成本与做市自动化（Stoll 三项里的第一项），不是 BCS 竞赛被解决。两篇文献必须同时读，才能避免「HFT 提高质量」或「HFT 破坏质量」的单句。</p><p><span class="marginnote">常见误区：初学者容易以为「市场变快 = 市场变好」。实际上要看清两件事：是所有人都快了（绝对延迟），还是某类参与者比别人快了（相对延迟）。前者压低交易的处理成本，后者只是重新分配谁抢得到单，质量指标随之分状态各走各路。</span></p><h3 id="场所竞争加速" tabindex="-1">场所竞争加速 <a class="header-anchor" href="#场所竞争加速" aria-label="Permalink to &quot;场所竞争加速&quot;">​</a></h3><p>Pagnotta–Philippon：投资者喜欢快的场所，场所投资速度吸引流，碎片化下可能过度投资速度。这与交易所之间的 make-take、tick 竞争并列。速度成为垂直差异化：对延迟敏感的流去托管场所，不敏感的流留在慢所或暗池。透明与匿名课的场所转移，在此多了延迟维度。</p><p><span class="marginnote">Boehmer、Fong 与 Wu 等跨国证据表明算法交易对流动性的符号随环境变。本课不报一个全球系数，只保留：符号取决于相对速度与供给是否撤退。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把质量指标对速度冲击回归：自动报价引入、光纤开通、主机托管、国际链路。必须分开短窗新闻质量与全日平均价差。发现用 Hasbrouck 长期乘数或定价误差；流动性用有效价差与深度；脆弱性用压力窗撤退。若发现改善而压力脆弱性升，政策含义不同于双改善。</p><p>理论基准：Biais–Foucault–Moinas 的均衡快速交易；BCS 的竞赛耗散。把「平均延迟」当处理变量会混淆绝对与相对。</p>',13)),(E(),r(s,null,{default:e(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Abs%5B%22%E7%BB%9D%E5%AF%B9%E5%BB%B6%E8%BF%9F%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20Proc%5B%22%E5%A4%84%E7%90%86%E6%88%90%E6%9C%AC%20%2F%20%E5%81%9A%E5%B8%82%E8%87%AA%E5%8A%A8%E5%8C%96%22%5D%0A%20%20Rel%5B%22%E7%9B%B8%E5%AF%B9%E5%BB%B6%E8%BF%9F%E4%BB%8D%E5%9C%A8%22%5D%20--%3E%20Race%5B%22%E7%8B%99%E5%87%BB%E6%9C%9F%E6%9D%83%20s%22%5D%0A%20%20Proc%20--%3E%20Qplus%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%E4%BB%B7%E5%B7%AE%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Race%20--%3E%20Qminus%5B%22%E9%80%9F%E5%BA%A6%E7%A8%8E%E4%B8%8E%E8%84%86%E5%BC%B1%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"平静期：自动化做市压低处理与库存成本，Menkveld 画像主导，质量升。新闻期：相对速度主导，Foucault–Hombert–Roşu 的发现腿与被捡同时升。压力期：反馈螺旋，速度加快的是空簿路径而不是补给。同一技术栈三态三色。市场设计续的 peg、颠簸、收盘竞价、熔断，都是在三态上切不同的刀，而不是「把市场再加速一点」。",-1)),(E(),r(s,null,{default:e(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Tech%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E5%8A%A0%E9%80%9F%E6%8A%80%E6%9C%AF%22%5D%20--%3E%20Calm%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%22%5D%0A%20%20Tech%20--%3E%20News%5B%22%E6%96%B0%E9%97%BB%E6%9C%9F%22%5D%0A%20%20Tech%20--%3E%20Stress%5B%22%E5%8E%8B%E5%8A%9B%E6%9C%9F%22%5D%0A%20%20Calm%20--%3E%20C1%5B%22%E5%81%9A%E5%B8%82%E8%87%AA%E5%8A%A8%E5%8C%96%E5%8E%8B%E4%BD%8E%E6%88%90%E6%9C%AC%EF%BC%9A%E4%BB%B7%E5%B7%AE%E6%94%B6%E7%AA%84%22%5D%0A%20%20News%20--%3E%20N1%5B%22%E7%9B%B8%E5%AF%B9%E9%80%9F%E5%BA%A6%E4%B8%BB%E5%AF%BC%EF%BC%9A%E5%8F%91%E7%8E%B0%E5%8A%A0%E5%BF%AB%EF%BC%8C%E8%A2%AB%E6%8D%A1%E4%B9%9F%E5%8A%A0%E5%BF%AB%22%5D%0A%20%20Stress%20--%3E%20S1%5B%22%E7%A9%BA%E7%B0%BF%E8%B7%AF%E5%BE%84%E6%9B%B4%E5%BF%AB%EF%BC%9A%E6%92%A4%E9%80%80%E5%BF%AB%E8%BF%87%E8%A1%A5%E7%BB%99%22%5D%0A%20%20C1%20--%3E%20Qup%5B%22%E5%B9%B3%E5%9D%87%E8%B4%A8%E9%87%8F%E6%94%B9%E5%96%84%22%5D%0A%20%20N1%20--%3E%20Mix%5B%22%E5%A5%BD%E5%9D%8F%E5%90%8C%E6%97%B6%E6%94%BE%E5%A4%A7%22%5D%0A%20%20S1%20--%3E%20Frag%5B%22%E8%84%86%E5%BC%B1%E6%80%A7%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">术语翻译：「狙击期权 \\(s\\)」就是把别人挂在盘口、还没来得及撤走的报价先一步吃掉的获利机会——像趁店员还没改价签就按旧价把商品买走。谁的相对延迟小，谁就握着这张「期权」；它越值钱，挂单的人越不敢挂。</span></p><p><span class="marginnote">数字实例：全市场延迟从 10 毫秒降到 1 毫秒，但 A 机构仍比 B 快 100 微秒，那么 A 抢 B 挂单的能力一点没变——决定被捡概率的是「差值」这 100 微秒，而不是 1 毫秒这个平均值。这就是为什么托管机房里大家挤在同一栋楼，竞争反而更凶。</span></p><p>对执行：平均质量改善不降低你在新闻窗的被捡。算法必须状态依赖，这与限价/市价阈值课一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「速度」在数据里常是代理（消息率、托管虚拟变量），不是毫秒。跨国制度差（涨跌停、印花税）会淹没速度效应。把质量写成单一指数（再对政策回归）会让发现与流动性互相抵消或双计。本课结束高频理论单元；具体规则从下一课 peg 与 D-limit 开始，不再抽象谈速度。</p><p><span class="marginnote">投资者保护若只看平均有效价差，会批准一切能压低平静期价差的加速，忽视分配与尾部。指标要分状态报告。</span></p><p>市场设计续从订单与场所规则动手：peg、颠簸、收盘拍卖、匹配算法，都是在三态上切一刀，而不是再把全市场的平均延迟削短一点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>绝对变快主要降处理成本；相对速度决定狙击租金。质量必须分平静、新闻、压力三态。</li><li>场所之间竞速可能过度投资延迟，碎片化放大。</li><li>HJM 式流动性改善与 BCS 式竞赛可以并存，单句评价 HFT 不够。</li><li>出处：Pagnotta and Philippon, <em>American Economic Review</em>, 2018；Hendershott, Jones and Menkveld, <em>Journal of Finance</em>, 2011。</li></ul>',9))])}const _=l(d,[["render",m]]);export{f as __pageData,_ as default};
